using System.Windows; using LibraryManager.Data; using LibraryManager.Services; using QuestPDF.Infrastructure;
namespace LibraryManager; public partial class App:Application { protected override void OnStartup(StartupEventArgs e){base.OnStartup(e); try { QuestPDF.Settings.License=LicenseType.Community; using var db=new LibraryDbContext(); db.Database.EnsureCreated(); DatabaseUpgradeService.EnsureBookMetadataColumns(db); SettingsService.Seed(); BackupService.AutoBackup(); } catch(Exception ex){MessageBox.Show("راه‌اندازی پایگاه داده ناموفق بود:\n"+ex.Message,"خطا",MessageBoxButton.OK,MessageBoxImage.Error); Shutdown();}} }